{
  "regions": [
    {
      "id": "r3",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "",
          "end": "join"
        },
        {
          "n": 2,
          "text": "सङ्गात्संजायते कामः कामात्क्रोधोभिजायते । इत्यादिगीतावचनात् । लालनात् ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "यत उक्तम्—लालनाद्वहवो दोषास्ताडनाद्वहवो गुणाः । तस्मात्पुत्रं च शिष्यं च",
          "end": "space"
        },
        {
          "n": 4,
          "text": "ताडयेन्न तु लालयेत् अनध्ययनाद्यतो विप्रत्वं विद्यानिबन्धनम् । तदुक्तं—",
          "end": "space"
        },
        {
          "n": 5,
          "text": "जन्मना ब्राह्मणो ज्ञेयः संस्कारैर्द्विज उच्यते । विद्यया याति विप्रत्वं त्रिभिः",
          "end": "space"
        },
        {
          "n": 6,
          "text": "श्रोत्रिय उच्यते ॥ इति । कुत्सितस्तनयः कुतनयः । तदुक्तं–कोटरान्तर्भवो",
          "end": "space"
        },
        {
          "n": 7,
          "text": "वह्निस्तरुमेकं दहिष्यति । कुपुत्रस्तु कुले जातः स्वकुलं नाशयेत्परम् ॥ मद्यान्मद्य-",
          "end": "hyphen"
        },
        {
          "n": 8,
          "text": "सेवनात् । अनवेक्षणादपरामर्शनात् । अप्रणयादननुरागप्रदर्शनात् । अनयादनी-",
          "end": "hyphen"
        },
        {
          "n": 9,
          "text": "त्याश्रयणेन । त्यागे व्यये प्रमादादनवधानतया । शार्दूलवि० छन्दः ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "दानं भोगो नाशस्तिस्रो गतयो भवन्ति वित्तस्य ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "यो न ददाति न भुंक्ते तस्य तृतीया गतिर्भवति ॥ ४३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "दानं पात्रे व्ययः । नाशो दानधर्माद्यभावे चौरादिनापहरणम् । न ददाति",
          "end": "space"
        },
        {
          "n": 2,
          "text": "वित्तमिति शेषः । तृतीया नाशलक्षणा । अतो धनाढ्येन दानभोगपरेण भाव्य-",
          "end": "hyphen"
        },
        {
          "n": 3,
          "text": "मित्यर्थः ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अथ दानशौण्डस्य धनराहित्यमपि शोभावहमित्याह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "मणिः शाणोल्लीढः समरविजयी हेतिनिहतो[१]",
          "end": "line"
        },
        {
          "n": 2,
          "text": "मदक्षीणो नागः शरदि सरिदाश्यानपुलिना[२] ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "कलाशेषश्चन्द्रः सुरतमृदिता बालवनिता[३]",
          "end": "line"
        },
        {
          "n": 4,
          "text": "तनिम्ना शोभन्ते गलितविभवाश्चार्थिषु[४] जनाः[५] ॥ ४४ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "शाणः शस्त्रनिशातनसाधनोपलविशेषः । तस्मिन्नुल्लीढः । तत्र घर्षणेनो-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "त्तेजित इत्यर्थः । हेतिः शस्त्रम् । हेतिभिर्निहतः क्षतः । मदेन दानस्रवणेन ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "नागो गजः । आश्यानमीषच्छुष्कम् । संयोगादेरातो धातोर्यण्वतः ( ८-२-४३ )",
          "end": "space"
        },
        {
          "n": 4,
          "text": "इति निष्ठानत्वम् । पुलिनं यस्याः सा । कलाशेषः षोडशांशमात्रावशिष्टः ।",
          "end": "space"
        },
        {
          "n": 5,
          "text": "कला तु षोडशो भागः इत्यमरः । स च देवतादिभिः पीतशेषत्वाच्छोभते ।",
          "end": "space"
        },
        {
          "n": 6,
          "text": "तदुक्तं कालिदासेन–पर्यायपीतस्य सुरैर्हिमांशोः कलाक्षयः श्लाघ्यतरो हि वृद्धेः ।",
          "end": "space"
        },
        {
          "n": 7,
          "text": "मृदिता लुलितेत्यर्थः । बालवनिता मुग्धाङ्गना । गलितः व्ययं प्रापितः विभवो",
          "end": "space"
        },
        {
          "n": 8,
          "text": "येषाम् । तनिम्ना कार्श्येन । पृथ्वादिभ्यादिमनिच् । अत्र प्रस्तुतानां जनानाम-",
          "end": "hyphen"
        }
      ],
      "uncertain": false,
      "note": null
    },
